import re
import unicodedata

def slugify(title: str, max_len: int = 50) -> str:
    # Step 1: Transliterate accented characters to ASCII and drop non-ASCII
    s = unicodedata.normalize('NFD', title)
    s = ''.join(c for c in s if ord(c) < 128)

    # Step 2: Lowercase
    s = s.lower()

    # Step 3: Replace runs of non-alphanumeric chars with a single hyphen, then strip
    s = re.sub(r'[^a-z0-9]+', '-', s)
    s = s.strip('-')

    # Step 5: If too long, truncate to the longest prefix of whole words
    if len(s) <= max_len:
        return s

    words = s.split('-')
    if len(words[0]) > max_len:
        return words[0][:max_len]

    result = []
    current_len = 0
    for word in words:
        if current_len == 0:
            if len(word) <= max_len:
                result.append(word)
                current_len = len(word)
            else:
                return word[:max_len]
        else:
            if current_len + 1 + len(word) <= max_len:
                result.append(word)
                current_len += 1 + len(word)
            else:
                return '-'.join(result)

    return '-'.join(result)
