def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""
    sorted_unique = sorted(set(nums))
    result = []
    i = 0
    while i < len(sorted_unique):
        start = sorted_unique[i]
        j = i
        while j + 1 < len(sorted_unique) and sorted_unique[j + 1] == sorted_unique[j] + 1:
            j += 1
        end = sorted_unique[j]
        if j - i + 1 >= 3:
            result.append(f"{start}..{end}")
        else:
            for k in range(i, j + 1):
                result.append(str(sorted_unique[k]))
        i = j + 1
    return ",".join(result)
