def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customer_data = {}  # key: lowercased name -> [first_name, total]

    for row in rows:
        customer = row.get("customer")
        if not customer:
            continue
        amount_str = row.get("amount")
        if not amount_str:
            continue

        name = customer.strip()
        if not name:
            continue
        amount_str = amount_str.strip()
        if not amount_str:
            continue

        try:
            cleaned = amount_str.replace(",", "").replace("$", "")
            is_negative = cleaned.startswith("-")
            if is_negative:
                cleaned = cleaned[1:]
            if cleaned.startswith("+"):
                cleaned = cleaned[1:]
            if not cleaned:
                continue
            value = float(cleaned)
            if is_negative:
                value = -value
        except (ValueError, TypeError):
            continue

        key = name.lower()
        if key not in customer_data:
            customer_data[key] = [name, 0.0]
        customer_data[key][1] += value

    result = []
    for first_name, total in customer_data.values():
        result.append((first_name, round(total, 2)))

    result.sort(key=lambda x: (-x[1], x[0]))

    return result[:n]
